/* Volta Studio — Styles */

/* Fonts */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;500;600;700;800;900&display=swap');

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --accent: #C4A77D;
  --accent-sage: #8B9A7E;
  --accent-terracotta: #C17C60;
  --accent-sand: #D4C4A8;
  --white: #FDFCFA;
  --gray: #8A8680;
  --serif: 'Playfair Display', Georgia, serif;
  --sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--sans);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* Typography */
h1, h2, h3, h4, h5 {
  font-family: var(--serif);
  font-weight: 600;
  line-height: 1.1;
}

h1 {
  font-size: clamp(2.5rem, 8vw, 6rem);
  font-weight: 700;
}

h2 {
  font-size: clamp(1.8rem, 4vw, 3rem);
}

h3 {
  font-size: clamp(1.2rem, 2vw, 1.5rem);
}

p {
  max-width: 65ch;
}

/* Layout */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 clamp(1.5rem, 5vw, 4rem);
}

.section {
  padding: clamp(3rem, 8vw, 6rem) 0;
}

/* Header / Navigation */
header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: var(--bg);
  padding: 1.5rem 0;
}

nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 2.5rem;
  list-style: none;
}

.nav-links a {
  font-size: 0.875rem;
  letter-spacing: 0.02em;
  transition: opacity 0.2s;
}

.nav-links a:hover {
  opacity: 0.6;
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  gap: 6px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  z-index: 200;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  transition: transform 0.3s, opacity 0.3s;
}

.menu-toggle.active span:nth-child(1) {
  transform: translateY(7.5px) rotate(45deg);
}

.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.active span:nth-child(3) {
  transform: translateY(-7.5px) rotate(-45deg);
}

/* Mobile Menu Overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s, visibility 0.3s;
}

.mobile-menu.active {
  opacity: 1;
  visibility: visible;
}

.mobile-menu ul {
  list-style: none;
  text-align: center;
}

.mobile-menu li {
  margin: 1.5rem 0;
}

.mobile-menu a {
  font-family: var(--serif);
  font-size: clamp(2rem, 8vw, 3.5rem);
  font-weight: 600;
}

/* Hero Section */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 6rem;
}

.hero h1 {
  max-width: 14ch;
  margin-bottom: 2rem;
}

/* Media Showcase */
.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  padding: 4rem 0;
}

.media-block {
  aspect-ratio: 4/5;
  border-radius: 4px;
}

.media-block:nth-child(1) { background: var(--accent-terracotta); }
.media-block:nth-child(2) { background: var(--accent-sage); }
.media-block:nth-child(3) { background: var(--accent-sand); }

/* Client Marquee */
.marquee-section {
  overflow: hidden;
  padding: 2rem 0;
  border-top: 1px solid rgba(26,26,26,0.1);
  border-bottom: 1px solid rgba(26,26,26,0.1);
}

.marquee-row {
  display: flex;
  gap: 3rem;
  padding: 0.75rem 0;
  font-family: var(--serif);
  font-size: clamp(1rem, 2vw, 1.25rem);
  font-weight: 500;
  white-space: nowrap;
}

.marquee-row span {
  display: inline-block;
  padding: 0 1.5rem;
  opacity: 0.8;
}

.marquee-row span::after {
  content: "◦";
  margin-left: 3rem;
  opacity: 0.4;
}

.marquee-row:last-child span::after {
  content: "◦";
}

/* Marquee Animations */
@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-row.left {
  animation: marquee-left 30s linear infinite;
}

.marquee-row.right {
  animation: marquee-right 30s linear infinite;
}

.marquee-wrapper {
  display: flex;
  overflow: hidden;
}

.marquee-wrapper .marquee-row {
  flex-shrink: 0;
}

/* About Section */
.about {
  max-width: 800px;
}

.about-label {
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  color: var(--gray);
}

.about p {
  font-size: clamp(1rem, 1.5vw, 1.125rem);
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

/* Founder Letter Page */
.founder-letter {
  min-height: 100vh;
  padding-top: 8rem;
  padding-bottom: 4rem;
}

.founder-letter .letter-content {
  max-width: 42rem;
  margin: 0 auto;
}

.founder-letter h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 3rem;
  max-width: 20ch;
}

.founder-letter .letter-body {
  font-size: clamp(1.1rem, 1.5vw, 1.25rem);
  line-height: 1.9;
}

.founder-letter .letter-body p {
  margin-bottom: 2rem;
}

.founder-letter .signature {
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.5rem;
  margin-top: 3rem;
}

/* Services Page */
.services-page {
  padding-top: 8rem;
}

.services-page h1 {
  font-size: clamp(2.5rem, 6vw, 4rem);
  margin-bottom: 4rem;
  max-width: 18ch;
}

.philosophy {
  max-width: 600px;
}

.philosophy h2 {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  margin-bottom: 1.5rem;
}

.philosophy p {
  font-size: clamp(1rem, 1.5vw, 1.125rem);
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

.divider {
  width: 60px;
  height: 1px;
  background: var(--text);
  margin: 4rem 0;
}

.service-details {
  padding-bottom: 6rem;
}

.service-details h2 {
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  margin-bottom: 3rem;
  max-width: 30ch;
}

.service-item {
  margin-bottom: 4rem;
}

.service-item h3 {
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  margin-bottom: 1rem;
}

.service-item p {
  font-size: clamp(1rem, 1.25vw, 1.125rem);
  line-height: 1.8;
  max-width: 55ch;
}

/* Clients Page */
.clients-page {
  padding-top: 8rem;
  padding-bottom: 6rem;
}

.clients-page h1 {
  font-size: clamp(2.5rem, 6vw, 4rem);
  margin-bottom: 4rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2rem;
}

.client-item h3 {
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  margin-bottom: 0.75rem;
}

.client-item p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--gray);
  max-width: 35ch;
}

/* Contact Page */
.contact-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 6rem;
}

.contact-page h1 {
  font-size: clamp(4rem, 15vw, 12rem);
  line-height: 0.9;
  margin-bottom: 4rem;
}

.contact-links {
  display: flex;
  gap: 3rem;
  flex-wrap: wrap;
}

.contact-links a {
  font-size: clamp(1rem, 1.5vw, 1.25rem);
  border-bottom: 1px solid var(--text);
  padding-bottom: 0.25rem;
  transition: opacity 0.2s;
}

.contact-links a:hover {
  opacity: 0.6;
}

/* Page Footer */
.page-footer {
  padding: 4rem 0;
  border-top: 1px solid rgba(26,26,26,0.1);
  margin-top: auto;
}

.page-footer p {
  font-size: 0.875rem;
  color: var(--gray);
}

/* Responsive */
@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .media-block {
    aspect-ratio: 16/10;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .contact-links {
    flex-direction: column;
    gap: 1.5rem;
  }

  .marquee-row {
    font-size: 0.875rem;
  }
}

@media (max-width: 480px) {
  .marquee-row.left,
  .marquee-row.right {
    animation-duration: 20s;
  }
}

